function Icon({name, size = 20}) {
  const paths = {
    heart: <><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21l7.8-7.5 1.1-1.1a5.5 5.5 0 0 0-.1-7.8Z"/><path d="M3.5 12h4l2-3.5 3.2 7 2.2-3.5h5.6"/></>,
    home: <><path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-6v-7h-4v7H4a1 1 0 0 1-1-1z"/></>,
    calendar: <><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></>,
    file: <><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h8"/></>,
    spark: <><path d="m12 3 1.9 5.8L20 11l-6.1 2.2L12 19l-1.9-5.8L4 11l6.1-2.2z"/><path d="m19 14 1.1 2.9L23 18l-2.9 1.1L19 22l-1.1-2.9L15 18l2.9-1.1z"/></>,
    user: <><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></>,
    settings: <><circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.7a8 8 0 0 1-1.8 1L15.7 21h-2.8l-.3-1.9a8 8 0 0 1-1.8-1l-1.7.7-1.4-2.4 1.4-1.1a7 7 0 0 1 0-2.1l-1.4-1.1 1.4-2.4 1.7.7a8 8 0 0 1 1.8-1L12.9 7h2.8l.3 1.9a8 8 0 0 1 1.8 1l1.7-.7 1.4 2.4-1.4 1.1a7 7 0 0 1-.1 2.3Z"/></>,
    search: <><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></>,
    bell: <><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></>,
    menu: <><path d="M4 6h16M4 12h16M4 18h16"/></>,
    close: <><path d="m18 6-12 12M6 6l12 12"/></>,
    hospital: <><path d="M3 21h18M5 21V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v16M9 21v-5h6v5M12 7v5M9.5 9.5h5"/></>,
    pin: <><path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></>,
    arrow: <><path d="M5 12h14M13 6l6 6-6 6"/></>,
    plus: <><path d="M12 5v14M5 12h14"/></>,
    shield: <><path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="m9 12 2 2 4-4"/></>,
    clock: <><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></>,
  };
  return <svg aria-hidden="true" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">{paths[name] || paths.spark}</svg>;
}

const initials = (name = '') => name.split(/\s+/).filter(Boolean).slice(0, 2).map(word => word[0].toUpperCase()).join('') || 'DR';
const pathWithId = (path, id) => path.replace('/0/', `/${encodeURIComponent(id)}/`).replace(/\/0$/, `/${encodeURIComponent(id)}`);
const api = async (url, options = {}) => {
  let response;
  try { response = await fetch(url, {credentials: 'same-origin', headers: {Accept: 'application/json', ...(options.body ? {'Content-Type': 'application/json'} : {})}, ...options}); }
  catch { throw new Error('Could not reach the server. Check your connection and sign in again.'); }
  let payload;
  try { payload = await response.json(); } catch { throw new Error('The server returned an invalid response.'); }
  if (!response.ok) throw new Error(payload.error || 'The request could not be completed.');
  return payload;
};

function Logo(){return <a className="hc-brand" href={app.view==='landing'||app.view==='account'?'/':(app.urls?.dashboard || '/dashboard')}><span className="hc-brand-mark"><Icon name="heart" size={22}/></span><span><strong>Healthcare</strong><small>Your Health • Our Priority</small></span></a>}
function Avatar({name = app.email}){return <span className="hc-avatar" aria-label={name}>{initials(name)}</span>}

const navItems = [
  {key:'dashboard',label:'Dashboard',icon:'home',url:'dashboard'},
  {key:'upload',label:'Upload Reports',icon:'plus',url:'upload'},
  {key:'explanation',label:'Healthcare Copilot Chat',icon:'spark',url:'explanation'},
  {key:'wellness',label:'Wellness Check-in',icon:'heart',url:'wellnessPage'},
  {key:'medications',label:'Medication Reminders',icon:'clock',url:'medicationsPage'},
  {key:'appointments',label:'Book Appointment',icon:'calendar',url:'appointments'},
  {key:'my-appointments',label:'My Appointments',icon:'clock',url:'appointments',hash:'#my-appointments'},
  {key:'history',label:'Medical Records',icon:'file',url:'history'},
  {key:'insights',label:'Health Insights',icon:'heart',url:'insights'},
  {key:'compare',label:'Compare Reports',icon:'file',url:'compare'},
  {key:'profile',label:'Patient Profile',icon:'user',url:'settings'},
];
function Sidebar({page, open, close}) {const activeKey=page==='dashboard'&&location.hash==='#health-insights'?'insights':page==='appointments'&&location.hash==='#my-appointments'?'my-appointments':page==='settings'&&location.hash==='#settings'?'settings':page==='settings'?'profile':page;return <><button className={`sidebar-scrim ${open?'visible':''}`} aria-label="Close menu" onClick={close}/><aside className={`hc-sidebar ${open?'is-open':''}`}><div className="sidebar-logo"><Logo/><button className="icon-button sidebar-close" onClick={close} aria-label="Close menu"><Icon name="close"/></button></div><div className="sidebar-section-label">WORKSPACE</div><nav aria-label="Main navigation">{navItems.map(item=><a key={item.key} href={`${app.urls[item.url]}${item.hash||''}`} className={`sidebar-link ${activeKey===item.key?'active':''}`} onClick={close}><Icon name={item.icon}/><span>{item.label}</span>{item.key==='my-appointments'&&(app.appointments||[]).length>0&&<span className="nav-count">{app.appointments.length}</span>}</a>)}</nav><div className="sidebar-help"><span className="help-icon"><Icon name="shield"/></span><strong>Your health data is private</strong><p>Records are protected by your signed-in account.</p></div><div className="sidebar-user"><Avatar/><span><strong>{app.email?.split('@')[0]||'Patient'}</strong><small>Patient account</small></span><a href={app.urls.settings} aria-label="Open patient profile"><Icon name="settings" size={18}/></a></div></aside></>}

function SearchBox(){const [query,setQuery]=useState(''),[items,setItems]=useState([]),[loading,setLoading]=useState(false),[error,setError]=useState(''),[open,setOpen]=useState(false);const timer=useRef();useEffect(()=>{clearTimeout(timer.current);if(query.trim().length<2){setItems([]);setError('');setLoading(false);return}timer.current=setTimeout(async()=>{setLoading(true);setError('');try{const data=await api(`${app.urls.doctorDirectory}?q=${encodeURIComponent(query.trim())}`);setItems(data.items||[])}catch(e){setError(e.message)}finally{setLoading(false)}},250);return()=>clearTimeout(timer.current)},[query]);const choose=doctor=>{const params=new URLSearchParams({state:doctor.state,district:doctor.district,city:doctor.city,hospital:String(doctor.hospital_id),doctor:String(doctor.id)});location.assign(`${app.urls.appointments}?${params.toString()}`)};return <div className="global-search"><Icon name="search"/><input value={query} onChange={e=>{setQuery(e.target.value);setOpen(true)}} onFocus={()=>setOpen(true)} onBlur={()=>setTimeout(()=>setOpen(false),140)} placeholder="Search doctors, hospitals, specialties" aria-label="Search doctors, hospitals, specialties" aria-expanded={open&&query.length>1}/>{query&&<button className="search-clear" onMouseDown={e=>e.preventDefault()} onClick={()=>setQuery('')} aria-label="Clear search">×</button>}{open&&query.length>1&&<div className="search-results">{loading?<p>Searching directory…</p>:error?<p className="text-error">{error}</p>:items.length?items.slice(0,6).map(item=><button key={item.id} onMouseDown={e=>e.preventDefault()} onClick={()=>choose(item)}><Avatar name={item.doctor_name}/><span><strong>{item.doctor_name}</strong><small>{item.specialty||'Specialty not listed'} · {item.hospital_name}</small></span></button>):<p>No matching doctor records. Try another name or specialty.</p>}</div>}</div>}

function Topbar({onMenu}){return <header className="hc-topbar"><button className="icon-button mobile-menu" onClick={onMenu} aria-label="Open navigation"><Icon name="menu"/></button><Logo/><SearchBox/><a className="icon-button notification-link" href={`${app.urls.appointments}#my-appointments`} aria-label="View appointment requests"><Icon name="bell"/></a><a className="top-profile" href={app.urls.settings}><Avatar/><span><strong>{app.email?.split('@')[0]||'Profile'}</strong><small>My account</small></span></a></header>}
function Footer(){return <footer className="hc-footer"><span><Icon name="shield" size={17}/> Secure <i/> Reliable <i/> Privacy First</span><strong>Healthcare</strong></footer>}
function FlashMessages(){return <div className="flash-stack">{(app.flashes||[]).map(([type,message],i)=><div key={i} className={`hc-flash ${type}`} role={type==='error'?'alert':'status'}>{message}</div>)}</div>}
function PageHeader({eyebrow,title,subtitle,action,className=''}){return <div className={`page-title-row ${className}`}><div><p className="hc-eyebrow">{eyebrow}</p><h1>{title}</h1>{subtitle&&<p className="hc-subtitle">{subtitle}</p>}</div>{action}</div>}

function StatCard({label,value,meta,icon,tone}){return <article className="stat-card"><span className={`stat-icon ${tone}`}><Icon name={icon}/></span><div><small>{label}</small><strong>{value}</strong><p>{meta}</p></div></article>}
function QuickLink({href,icon,title,copy,tone='blue'}){return <a className="quick-link" href={href}><span className={`quick-link-icon ${tone}`}><Icon name={icon}/></span><span><strong>{title}</strong><small>{copy}</small></span><Icon name="arrow" size={17}/></a>}

function CarePathway(){return <section className="panel care-pathway-panel" aria-labelledby="care-pathway-title"><div className="panel-heading"><div><p className="hc-eyebrow">A SIMPLE WAY TO START</p><h2 id="care-pathway-title">Your health, step by step</h2><p className="panel-subtitle">A clear guide to using your Healthcare workspace.</p></div><span className="pathway-badge"><Icon name="shield" size={15}/> Private workspace</span></div><div className="care-pathway"><a className="pathway-step" href={app.urls.upload}><span className="pathway-number">01</span><span className="pathway-icon mint"><Icon name="file" size={23}/></span><strong>Upload</strong><small>Save a report securely</small></a><span className="pathway-connector" aria-hidden="true"><i/></span><a className="pathway-step" href={app.urls.explanation}><span className="pathway-number">02</span><span className="pathway-icon aqua"><Icon name="spark" size={23}/></span><strong>Understand</strong><small>Ask about report terms</small></a><span className="pathway-connector" aria-hidden="true"><i/></span><a className="pathway-step" href={app.urls.insights}><span className="pathway-number">03</span><span className="pathway-icon lavender"><Icon name="heart" size={23}/></span><strong>Review</strong><small>See values with ranges</small></a></div><p className="pathway-note">Healthcare provides educational information. Your clinician remains your source for medical advice.</p></section>}

function HomePage(){const appointments=app.appointments||[],reports=app.reports||[],medications=app.medications||[],measurements=app.measurements||[];return <div className="dashboard-home">
  <section className="welcome-banner"><div className="welcome-copy"><span className="welcome-badge"><Icon name="heart" size={15}/> YOUR PERSONAL HEALTH SPACE</span><h1>Welcome back!</h1><p>Your health information, organized in one calm and easy-to-use place.</p><a className="primary-button" href={app.urls.upload}>Upload a report <Icon name="arrow" size={17}/></a></div><div className="welcome-art" aria-hidden="true"><span className="art-orbit orbit-one"/><span className="art-orbit orbit-two"/><span className="art-cross">+</span><span className="art-heart"><Icon name="heart" size={48}/></span><span className="art-pulse pulse-one"/><span className="art-pulse pulse-two"/></div></section>
  <div className="dashboard-section-heading"><div><p className="hc-eyebrow">YOUR OVERVIEW</p><h2>At a glance</h2></div><span className="dashboard-date">{app.today||''}</span></div>
  <div className="stats-grid"><StatCard label="Total documents" value={reports.length} meta={reports.length===1?'Report saved to your account':'Reports saved to your account'} icon="file" tone="blue"/><StatCard label="Active medicines" value={medications.length} meta={medications.length===1?'Reminder in your schedule':'Reminders in your schedule'} icon="clock" tone="purple"/><StatCard label="Abnormal lab results" value={app.abnormal_result_count||0} meta="Outside the range printed on your reports" icon="heart" tone="coral"/></div>
  <CarePathway/>
  <div className="dashboard-section-heading quick-access-heading"><div><p className="hc-eyebrow">QUICK ACCESS</p><h2>What would you like to do?</h2></div></div>
  <div className="quick-links-grid dashboard-quick-links"><QuickLink href={app.urls.history} icon="file" title="View medical records" copy={`${reports.length} ${reports.length===1?'report':'reports'} saved`} tone="blue"/><QuickLink href={app.urls.explanation} icon="spark" title="Ask about a report" copy="Get a simple explanation" tone="purple"/><QuickLink href={app.urls.insights} icon="heart" title="Explore health insights" copy={measurements.length?`${measurements.length} reported measurements`:'See values from your reports'} tone="teal"/></div>
  <section className="panel upcoming-panel dashboard-appointments"><div className="panel-heading"><div><p className="hc-eyebrow">MY CARE</p><h2>Upcoming appointment requests</h2><p className="panel-subtitle">Requests are not confirmed bookings.</p></div><a className="panel-link" href={`${app.urls.appointments}#my-appointments`}>View all <Icon name="arrow" size={15}/></a></div>{appointments.length?appointments.slice(0,3).map(item=><AppointmentRow key={item.id} item={item}/>):<div className="empty-state compact"><span className="empty-icon"><Icon name="calendar"/></span><strong>No upcoming requests</strong><p>Requests you save will appear here.</p><a className="text-link" href={app.urls.appointments}>Find a hospital</a></div>}</section>
</div>}

function AppointmentRow({item}){return <article className="appointment-row"><span className="appointment-date"><strong>{(item.appointment_date||'').slice(8,10)||'—'}</strong><small>{(item.appointment_date||'').slice(0,7)||'Request'}</small></span><div><strong>{item.doctor_name||'Doctor not selected'}</strong><small>{item.hospital_name}</small><small>{item.city}, {item.state}</small><span className="status-pill pending">{item.booking_mode==='legacy_request'?'Request saved':'Demo · awaiting confirmation'}</span></div></article>}
function ReportRow({report}){return <a className="report-row" href={pathWithId(app.urls.viewReport,report.id)}><span className="report-icon"><Icon name="file" size={18}/></span><span><strong>{report.title}</strong><small>{report.created_at||'Saved report'}</small></span><Icon name="arrow" size={16}/></a>}
function WellnessForm(){const w=app.wellness;return <section className="panel wellness-edit" id="wellness-form"><div className="panel-heading"><div><p className="hc-eyebrow">{app.today||'TODAY'}</p><h2>Wellness check-in</h2></div></div><form method="post" action={app.urls.wellness} className="wellness-form"><label>Water glasses<input type="number" name="water_glasses" min="0" max="30" defaultValue={w?.water_glasses||0} required/></label><label>Sleep hours<input type="number" name="sleep_hours" min="0" max="24" step="0.25" defaultValue={w?.sleep_hours||0} required/></label><label>Exercise minutes<input type="number" name="exercise_minutes" min="0" max="1440" defaultValue={w?.exercise_minutes||0} required/></label><label>Steps<input type="number" name="steps" min="0" max="100000" defaultValue={w?.steps||0} required/></label><label className="wide-field">Today's focus<input name="focus" maxLength="120" defaultValue={w?.focus||''} placeholder="Optional"/></label><button className="primary-button">Save check-in</button></form></section>}

function WellnessPage(){const w=app.wellness,history=app.wellness_history||[],tips=app.ai_wellness_suggestions||app.wellness_suggestions||[];return <><PageHeader eyebrow="DAILY WELLNESS" title="Wellness check-in" subtitle="Record your daily habits and review the entries you have saved."/><WellnessForm/><section className="panel wellness-history"><div className="panel-heading"><div><p className="hc-eyebrow">YOUR ENTRIES</p><h2>Recent check-ins</h2></div></div>{history.length?<div className="wellness-history-list">{history.map(row=><article className="wellness-history-row" key={row.log_date}><strong>{row.log_date}</strong><span>{row.sleep_hours} h sleep</span><span>{row.water_glasses} water glasses</span><span>{row.exercise_minutes} min activity</span><span>{row.steps.toLocaleString()} steps</span></article>)}</div>:<div className="empty-state"><strong>No check-ins saved yet</strong><p>Your entries will appear here after you save one.</p></div>}<h3 className="wellness-reflection-title">Gentle reflections</h3>{app.ai_wellness_error&&<p className="hc-error" role="alert">{app.ai_wellness_error}</p>}<ul className="health-tip-list">{tips.map((tip,index)=><li key={index}>{tip}</li>)}</ul><form method="post" action={app.urls.aiIdeas} className="wellness-ai-form"><label><input type="checkbox" name="share_daily_log" value="yes" required/> I agree to send today's check-in values to the AI service to generate suggestions.</label><button className="secondary-button" disabled={!w}>Generate optional AI suggestions</button></form><p className="panel-subtitle">Suggestions are general information, not medical advice. Follow your clinician's instructions.</p></section></>}

function MedicationPage(){return <><PageHeader eyebrow="YOUR SCHEDULE" title="Medication reminders" subtitle="Manage reminders for medicines and schedules provided by your clinician."/><MedicationPanel/></>}

function MedicationPanel(){const items=app.medications||[];const [status,setStatus]=useState('');const [enabled,setEnabled]=useState(false);useEffect(()=>{if(!enabled||!('Notification' in window)||Notification.permission!=='granted')return;const check=()=>{const now=new Date(),time=now.toTimeString().slice(0,5),day=now.toISOString().slice(0,10);items.forEach(item=>{if(item.reminder_time!==time)return;const key=`careconnect-med-${day}-${item.id}`;if(localStorage.getItem(key))return;new Notification('Medicine reminder',{body:`Scheduled reminder: ${item.name}`});localStorage.setItem(key,'1')})};check();const timer=window.setInterval(check,15000);return()=>window.clearInterval(timer)},[enabled,items]);const enable=async()=>{if(!('Notification' in window)){setStatus('This browser does not support notifications. The schedule remains available here.');return}const permission=Notification.permission==='default'?await Notification.requestPermission():Notification.permission;if(permission!=='granted'){setStatus('Notifications are not enabled. The schedule remains available here.');return}setEnabled(true);setStatus('Browser reminders run while this dashboard stays open.')};return <section className="panel medication-panel"><div className="panel-heading"><div><p className="hc-eyebrow">MEDICATION SCHEDULE</p><h2>Medication reminders</h2></div><button type="button" className="secondary-button" onClick={enable} disabled={enabled||!items.length}>{enabled?'Reminders on':'Enable browser reminders'}</button></div>{items.length?<div className="medication-list">{items.map(item=><article className="medication-row" key={item.id}><span className="stat-icon purple"><Icon name="clock" size={18}/></span><span><strong>{item.name}</strong><small>{item.instructions||'Follow instructions from your clinician'}</small></span><time>{item.reminder_time}</time><form method="post" action={pathWithId(app.urls.deleteMedication,item.id)} onSubmit={e=>{if(!confirm(`Remove the reminder for ${item.name}?`))e.preventDefault()}}><button className="text-button" aria-label={`Remove ${item.name} reminder`}>Remove</button></form></article>)}</div>:<div className="empty-inline"><span>No medication reminders saved.</span></div>}<form method="post" action={app.urls.medication} className="medication-form"><label>Medicine name<input name="name" maxLength="100" required placeholder="Name from your prescription"/></label><label>Instructions<input name="instructions" maxLength="300" placeholder="Optional notes"/></label><label>Reminder time<input name="reminder_time" type="time" required/></label><button className="primary-button"><Icon name="plus" size={16}/> Add reminder</button></form>{status&&<p className="panel-subtitle" role="status">{status}</p>}</section>}

function HealthInsights(){const [items,setItems]=useState(app.measurements||[]),[biomarkers,setBiomarkers]=useState([...new Set((app.measurements||[]).map(row=>row.name))]),[biomarker,setBiomarker]=useState((app.measurements||[])[0]?.name||''),[start,setStart]=useState(''),[end,setEnd]=useState(''),[loading,setLoading]=useState(false),[error,setError]=useState('');useEffect(()=>{let live=true;const controller=new AbortController();const query=new URLSearchParams();if(biomarker)query.set('biomarker',biomarker);if(start)query.set('from',start);if(end)query.set('to',end);setLoading(true);setError('');api(`${app.urls.healthInsights}?${query}`,{signal:controller.signal}).then(data=>{if(live){setItems(data.items||[]);setBiomarkers(data.biomarkers||[]);if(!biomarker&&data.biomarkers?.length)setBiomarker(data.biomarkers[0])}}).catch(e=>{if(live&&e.name!=='AbortError')setError(e.message)}).finally(()=>live&&setLoading(false));return()=>{live=false;controller.abort()}},[biomarker,start,end]);const sorted=[...items].sort((a,b)=>a.date.localeCompare(b.date));const values=sorted.map(row=>row.value),min=Math.min(...values),max=Math.max(...values),span=max-min||1;const points=sorted.map((row,i)=>`${sorted.length===1?180:24+i*312/(sorted.length-1)},${154-(row.value-min)*116/span}`).join(' ');return <><PageHeader eyebrow="YOUR REPORT DATA" title="Health Insights" subtitle="Review measurements and reference ranges extracted from your saved reports."/><section className="panel insights-panel" id="health-insights"><div className="panel-heading"><div><p className="hc-eyebrow">BIOMARKER TRENDS</p><h2>Values from your reports</h2><p className="panel-subtitle">This page uses printed report ranges and does not interpret image-only results without extracted text.</p></div></div><div className="insight-filters"><label>Biomarker<select value={biomarker} onChange={e=>setBiomarker(e.target.value)}><option value="">Choose a biomarker</option>{biomarkers.map(name=><option key={name}>{name}</option>)}</select></label><label>From<input type="date" value={start} onChange={e=>setStart(e.target.value)}/></label><label>To<input type="date" value={end} onChange={e=>setEnd(e.target.value)}/></label></div>{error?<p className="hc-error" role="alert">{error}</p>:loading?<div className="loading-row"><span className="spinner"/> Loading report measurements…</div>:sorted.length?<><div className="trend-chart" role="img" aria-label={`Trend of ${biomarker||'reported biomarker'} across ${sorted.length} extracted results`}><svg viewBox="0 0 360 180" preserveAspectRatio="none"><line x1="24" y1="154" x2="336" y2="154"/><line x1="24" y1="96" x2="336" y2="96"/><line x1="24" y1="38" x2="336" y2="38"/>{sorted.length>1&&<polyline points={points}/>}{sorted.map((row,i)=><circle key={`${row.report_id}-${i}`} cx={sorted.length===1?180:24+i*312/(sorted.length-1)} cy={154-(row.value-min)*116/span} r="4"><title>{row.name}: {row.value} {row.unit} · {row.date}</title></circle>)}</svg><div className="trend-labels"><span>{sorted[0].date||'Date unavailable'}</span><span>{sorted[sorted.length-1].date||'Date unavailable'}</span></div></div><div className="measurement-list">{sorted.map((row,index)=><article key={`${row.report_id}-${index}`} className={`measurement-result ${row.abnormal?'abnormal':''}`}><div><strong>{row.name}</strong><small>{row.report_title} · {row.date||'Date unavailable'}</small></div><span>{row.value} {row.unit}</span><small>Reference: {row.reference_range}</small>{row.abnormal&&<b>Outside printed range</b>}</article>)}</div></>:<div className="empty-state"><span className="empty-icon"><Icon name="heart"/></span><strong>No ranged lab results found in saved report text</strong><p>Upload a text-readable report that includes values and reference ranges. No medical thresholds are assumed.</p></div>}</section></>}

function AppointmentFinder(){const params=new URLSearchParams(location.search);const [state,setState]=useState(''),[district,setDistrict]=useState(''),[city,setCity]=useState(''),[hospital,setHospital]=useState('');const [states,setStates]=useState([]),[districts,setDistricts]=useState([]),[cities,setCities]=useState([]),[hospitals,setHospitals]=useState([]);const [loading,setLoading]=useState(''),[error,setError]=useState(''),[message,setMessage]=useState('Loading states…');const version=useRef({});
  useEffect(()=>{let alive=true;api(app.urls.states).then(result=>{if(alive){setStates(result.items||[]);setMessage(result.items?.length?`${result.items.length} states and union territories available.`:'No states are loaded yet. Import the location dataset.')}}).catch(e=>alive&&setError(e.message));return()=>{alive=false}},[]);
  useEffect(()=>{const s=params.get('state'),d=params.get('district'),c=params.get('city'),h=params.get('hospital');if(!s||!d||!c||!h)return;let alive=true;const loadSelection=async()=>{try{setError('');setLoading('location');const districtsResult=await api(`${app.urls.districts}?${new URLSearchParams({state:s})}`);if(!alive)return;setState(s);setDistricts(districtsResult.items||[]);const citiesResult=await api(`${app.urls.cities}?${new URLSearchParams({state:s,district:d})}`);if(!alive)return;setDistrict(d);setCities(citiesResult.items||[]);const hospitalsResult=await api(`${app.urls.hospitals}?${new URLSearchParams({state:s,district:d,city:c})}`);if(!alive)return;setCity(c);setHospitals(hospitalsResult.items||[]);if(!(hospitalsResult.items||[]).some(row=>String(row.id)===h))return;setHospital(h);setMessage('Hospital selected. Choose a date and time to continue.')}catch(e){if(alive)setError(e.message)}finally{if(alive)setLoading('')}};loadSelection();return()=>{alive=false}},[]);
  const invalidate=(...keys)=>keys.forEach(key=>{version.current[key]=(version.current[key]||0)+1});
  const resetFrom=level=>{if(level==='state'){setDistrict('');setDistricts([])}if(['state','district'].includes(level)){setCity('');setCities([])}if(['state','district','city'].includes(level)){setHospital('');setHospitals([])}};
  const loadNext=async(key,label,action,save,empty)=>{const n=version.current[key]=(version.current[key]||0)+1;setLoading(key);setError('');setMessage(`Loading ${label}…`);try{const result=await action();if(version.current[key]!==n)return;const rows=result.items||[];save(rows);setMessage(rows.length?`${rows.length} ${label} available.`:empty)}catch(e){if(version.current[key]===n){setError(e.message);setMessage('')}}finally{if(version.current[key]===n)setLoading('')}};
  const onState=next=>{invalidate('district','city','hospital');setState(next);resetFrom('state');if(!next){setMessage('Select a state to find its districts.');return}loadNext('district','districts',()=>api(`${app.urls.districts}?${new URLSearchParams({state:next})}`),setDistricts,'No districts are listed for this state.')};
  const onDistrict=next=>{invalidate('city','hospital');setDistrict(next);resetFrom('district');if(!next){setMessage('Select a district to find its cities/towns.');return}loadNext('city','cities and towns',()=>api(`${app.urls.cities}?${new URLSearchParams({state,district:next})}`),setCities,'No cities or towns are listed for this district.')};
  const onCity=next=>{invalidate('hospital');setCity(next);resetFrom('city');if(!next){setMessage('Select a city/town to find hospitals.');return}loadNext('hospital','hospitals',()=>api(`${app.urls.hospitals}?${new URLSearchParams({state,district,city:next})}`),setHospitals,'No hospital records are listed for this city yet. Import verified hospital data to populate this list.')};
  const onHospital=next=>{setHospital(next);if(next)setMessage('Hospital selected. Choose a date and time to continue.');else setMessage('Choose a hospital from the selected city.')};
  return <section className="panel booking-panel" id="appointment-booking"><div className="panel-heading"><div><p className="hc-eyebrow">FIND CARE</p><h2>Book an appointment</h2><p className="panel-subtitle">Select a location, then choose a hospital listed in that city.</p></div><span className="booking-step-count">4 steps</span></div><ol className="booking-steps">{['State','District','City / town','Hospital'].map((label,i)=><li key={label} className={i===0||[district,city,hospital][i-1]?'step-ready':''}><span>{String(i+1).padStart(2,'0')}</span>{label}</li>)}</ol><p className={`directory-message ${error?'has-error':''}`} role={error?'alert':'status'}>{error||message}</p><form method="post" action={app.urls.book} className="booking-grid" onSubmit={event=>{if(!hospital){event.preventDefault();setError('Choose a hospital before saving a request.')}}}>
    <label>State<select required value={state} onChange={e=>onState(e.target.value)}><option value="">Choose a state</option>{states.map(row=><option key={row.name} value={row.name}>{row.name}</option>)}</select></label>
    <label>District<select required disabled={!state||loading==='district'} value={district} onChange={e=>onDistrict(e.target.value)}><option value="">{districts.length?'Choose a district':loading==='district'?'Loading districts…':'Select state first'}</option>{districts.map(row=><option key={row.name} value={row.name}>{row.name}</option>)}</select></label>
    <label>City / town<select required disabled={!district||loading==='city'} value={city} onChange={e=>onCity(e.target.value)}><option value="">{cities.length?'Choose a city/town':loading==='city'?'Loading cities…':'Select district first'}</option>{cities.map(row=><option key={row.name} value={row.name}>{row.name}</option>)}</select></label>
    <label>Hospital<select required disabled={!city||loading==='hospital'} name="hospital_id" value={hospital} onChange={e=>onHospital(e.target.value)}><option value="">{loading==='hospital'?'Loading hospitals…':!city?'Select city first':hospitals.length?'Choose a hospital':'No hospitals listed for this city'}</option>{hospitals.map(row=><option key={row.id} value={row.id}>{row.hospital_name}{row.source_type==='spreadsheet_unverified'?' — unverified, confirm locally':''}</option>)}</select></label>
    <label>Date<input type="date" name="appointment_date" min={new Date().toISOString().slice(0,10)} required/></label><label>Preferred time<select name="time_slot" required><option value="">Choose a time window</option><option value="morning">Morning</option><option value="afternoon">Afternoon</option><option value="evening">Evening</option></select></label><div className="booking-submit"><button className="primary-button" disabled={!hospital}>Save demo request <Icon name="arrow" size={17}/></button></div></form>{hospital&&<p className="booking-disclaimer">This saves a demo request only. It does not contact the hospital or confirm an available slot.</p>}</section>
}

function DoctorCard({doctor}){const params=new URLSearchParams({state:doctor.state,district:doctor.district,city:doctor.city,hospital:String(doctor.hospital_id),doctor:String(doctor.id)});return <article className="doctor-card"><div className="doctor-card-top"><Avatar name={doctor.doctor_name}/><span className={`verification-tag ${doctor.verification_status==='verified'?'checked':''}`}>{doctor.verification_status==='verified'?'Registration checked':'Unverified listing'}</span></div><h3>{doctor.doctor_name}</h3><p className="doctor-specialty">{doctor.specialty||'Specialty not listed'}</p><div className="doctor-meta"><span><Icon name="hospital" size={16}/>{doctor.hospital_name}</span><span><Icon name="pin" size={16}/>{[doctor.city,doctor.district,doctor.state].filter(Boolean).join(', ')}</span></div><a className="secondary-button full-button" href={`${app.urls.appointments}?${params.toString()}`}>Book appointment <Icon name="arrow" size={16}/></a></article>}
function DoctorsDirectory(){const [doctors,setDoctors]=useState([]),[specialties,setSpecialties]=useState([]),[specialty,setSpecialty]=useState(''),[query,setQuery]=useState(''),[loading,setLoading]=useState(true),[error,setError]=useState('');useEffect(()=>{let live=true;const controller=new AbortController();const timer=setTimeout(async()=>{setLoading(true);try{const url=new URL(app.urls.doctorDirectory,location.origin);if(query.trim())url.searchParams.set('q',query.trim());if(specialty)url.searchParams.set('specialty',specialty);const result=await api(url.pathname+url.search,{signal:controller.signal});if(live){setDoctors(result.items||[]);setSpecialties(result.specialties||[]);setError('')}}catch(e){if(live&&e.name!=='AbortError')setError(e.message)}finally{if(live)setLoading(false)}},150);return()=>{live=false;clearTimeout(timer);controller.abort()}},[query,specialty]);return <section className="panel doctors-directory"><div className="panel-heading"><div><p className="hc-eyebrow">DIRECTORY</p><h2>Available doctors</h2><p className="panel-subtitle">Only doctor records associated with an imported hospital appear here.</p></div></div><div className="doctor-filters"><label className="filter-search"><Icon name="search" size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search name or specialty" aria-label="Search doctor name or specialty"/></label><label className="specialty-filter"><span className="sr-only">Filter by specialization</span><select value={specialty} onChange={e=>setSpecialty(e.target.value)}><option value="">All specializations</option>{specialties.map(item=><option key={item} value={item}>{item}</option>)}</select></label></div>{error?<div className="empty-state"><strong>Could not load the doctor directory</strong><p>{error}</p></div>:loading?<div className="loading-row"><span className="spinner"/> Loading doctor records…</div>:doctors.length?<div className="doctor-grid">{doctors.map(doctor=><DoctorCard key={doctor.id} doctor={doctor}/>)}</div>:<div className="empty-state"><span className="empty-icon"><Icon name="user"/></span><strong>No doctor records available yet</strong><p>Doctor names aren't included in the hospital list. Import doctor records after checking each hospital association.</p></div>}</section>}

function AppointmentsPage(){const rows=app.appointments||[];return <><PageHeader eyebrow="APPOINTMENT DIRECTORY" title="Find your care team" subtitle="Browse the directory and save a request for a listed hospital."/><AppointmentFinder/><DoctorsDirectory/><AppointmentsList rows={rows}/>{app.is_hospital_admin&&<AdminTools/>}</>}
function AppointmentsList({rows}){return <section className="panel" id="my-appointments"><div className="panel-heading"><div><p className="hc-eyebrow">YOUR ACCOUNT</p><h2>My appointments</h2><p className="panel-subtitle">A saved demo request is not a confirmed appointment.</p></div></div>{rows.length?<div className="appointment-list">{rows.map(row=><div className="appointment-list-card" key={row.id}><AppointmentRow item={row}/><div className="appointment-detail"><span><Icon name="calendar" size={16}/>{row.appointment_date||row.appointment_at}</span><span><Icon name="clock" size={16}/>{row.time_slot||'Time not specified'}</span><span className="status-pill pending">{row.booking_mode==='legacy_request'?'Legacy request':'Demo · confirmation required'}</span></div></div>)}</div>:<div className="empty-state"><span className="empty-icon"><Icon name="calendar"/></span><strong>No appointment requests yet</strong><p>Requests you save will be listed here. Call the hospital to arrange care.</p></div>}</section>}
function AdminTools(){return <section className="panel admin-tools"><p className="hc-eyebrow">DIRECTORY ADMIN</p><h2>Import directory records</h2><p>Use official hospital directory data or records independently verified by your team.</p><form method="post" encType="multipart/form-data" action={app.urls.directoryUpload} className="upload-inline"><label>Hospital CSV<input type="file" name="directory_file" accept=".csv,text/csv" required/></label><button className="secondary-button">Import hospitals</button></form><a href={app.urls.directoryTemplate}>Hospital CSV template</a><hr/><form method="post" encType="multipart/form-data" action={app.urls.doctorUpload} className="upload-inline"><label>Doctor CSV<input type="file" name="doctor_file" accept=".csv,text/csv" required/></label><button className="secondary-button">Import doctors</button></form><a href={app.urls.doctorTemplate}>Doctor CSV template</a></section>}

function RecordsPage(){const reports=app.reports||[];return <><PageHeader eyebrow="MEDICAL RECORDS" title="Your medical records" subtitle="Private reports saved to your account." action={<a className="primary-button" href={app.urls.upload}><Icon name="plus" size={17}/> Upload record</a>}/><section className="panel records-panel"><div className="panel-heading"><div><p className="hc-eyebrow">REPORT LIBRARY</p><h2>{reports.length} {reports.length===1?'record':'records'}</h2></div></div>{reports.length?<div className="records-list">{reports.map(report=><article className="record-card" key={report.id}><span className="record-type"><Icon name="file"/></span><div className="record-info"><strong>{report.title}</strong><small>{report.mime_type||'Saved health report'} · {report.created_at}</small>{report.explanation&&<span className="record-explained">AI explanation available</span>}</div><a className="secondary-button" href={pathWithId(app.urls.viewReport,report.id)}>View report <Icon name="arrow" size={16}/></a></article>)}</div>:<div className="empty-state"><span className="empty-icon"><Icon name="file"/></span><strong>No medical records saved</strong><p>Upload a PDF, JPG, or PNG report to keep it in your private workspace.</p><a className="primary-button" href={app.urls.upload}>Upload your first report</a></div>}</section></>}
function UploadPage(){const [busy,setBusy]=useState(false),[error,setError]=useState('');return <><PageHeader eyebrow="MEDICAL RECORDS" title="Upload a report" subtitle="Add a PDF, PNG, or JPG to your private report library."/><form className="panel upload-panel" method="post" action={app.urls.upload} encType="multipart/form-data" onSubmit={event=>{const file=event.currentTarget.elements.file.files[0];if(!file)return;if(file.size>2*1024*1024){event.preventDefault();setError('This file is larger than the 2 MB upload limit.');return}setError('');setBusy(true)}}><label className="upload-drop"><span className="upload-icon"><Icon name="file" size={28}/></span><strong>Choose your report</strong><small>PDF, JPG or PNG - maximum 2 MB</small><input type="file" name="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" required onChange={e=>{const file=e.target.files[0];if(file&&file.size>2*1024*1024)setError('This file is larger than the 2 MB upload limit.')}}/></label>{error&&<p className="hc-error" role="alert">{error}</p>}<button className="primary-button" disabled={busy}>{busy?<><span className="spinner"/> Uploading report...</>:'Save report securely'}</button><p className="panel-subtitle">Text extraction depends on report readability and the installed PDF/OCR tools. Verify extracted values against your original file.</p></form></>}

function AssistantPage(){const reports=app.reports||[];const [reportId,setReportId]=useState(''),[messages,setMessages]=useState([]),[question,setQuestion]=useState(''),[loading,setLoading]=useState(false),[error,setError]=useState('');const send=async text=>{const value=(text??question).trim();if(!value||loading)return;setMessages(old=>[...old,{role:'user',content:value}]);setQuestion('');setLoading(true);setError('');try{const result=await api(app.urls.assistant,{method:'POST',body:JSON.stringify({question:value,...(reportId?{report_id:Number(reportId)}:{})})});setMessages(old=>[...old,{role:'assistant',content:result.answer}])}catch(e){setError(e.message)}finally{setLoading(false)}};return <><PageHeader eyebrow="HEALTHCARE COPILOT CHAT" title="Ask about your health information" subtitle="Get simple explanations of health terms and your selected report."/><section className="assistant-panel panel"><div className="assistant-intro"><span className="assistant-mark"><Icon name="spark" size={22}/></span><div><strong>Healthcare Copilot</strong><small>General information - not medical care</small></div></div><label className="chat-report-select">Use report context (optional)<select value={reportId} onChange={e=>setReportId(e.target.value)}><option value="">No report selected</option>{reports.map(report=><option key={report.id} value={report.id}>{report.title} ? {report.created_at}</option>)}</select></label><div className="chat-messages" aria-live="polite">{!messages.length&&<div className="assistant-empty"><span className="assistant-empty-icon"><Icon name="heart" size={28}/></span><h2>What would you like help understanding?</h2><p>Try a report question or ask about a medical term.</p><div className="prompt-chips"><button onClick={()=>send('Can you explain the results and reference ranges in my selected report?')}>Explain my selected report</button><button onClick={()=>send('What does this medical term mean in simple language?')}>Explain a medical term</button><button onClick={()=>send('What should I ask my clinician about this report?')}>Prepare questions for my clinician</button></div></div>}{messages.map((message,index)=><div className={'chat-message '+message.role} key={index}><span className="chat-avatar">{message.role==='assistant'?<Icon name="heart" size={16}/>:initials(app.email)}</span><div><small>{message.role==='assistant'?'Healthcare Copilot':'You'}</small><p>{message.content}</p></div></div>)}{loading&&<div className="chat-message assistant"><span className="chat-avatar"><Icon name="heart" size={16}/></span><div><small>Healthcare Copilot</small><p className="typing"><i/><i/><i/> Thinking?</p></div></div>}{error&&<p className="hc-error" role="alert">{error}</p>}</div><form className="chat-compose" onSubmit={event=>{event.preventDefault();send()}}><label className="sr-only" htmlFor="assistant-question">Your health question</label><textarea id="assistant-question" value={question} onChange={e=>setQuestion(e.target.value)} maxLength={1000} rows={2} placeholder="Ask about your selected report or a health term?" disabled={loading}/><button className="primary-button" disabled={loading||!question.trim()}>Send <Icon name="arrow" size={17}/></button></form><p className="assistant-disclaimer">AI-generated information is educational only. It does not diagnose conditions or replace professional medical advice. Do not change medicines based on this chat.</p></section></>}

function SettingsPage(){const user=app.user||{};return <><PageHeader eyebrow="YOUR ACCOUNT" title="Profile & settings" subtitle="Update the contact details associated with your account."/><section className="panel profile-panel" id="profile"><div className="profile-heading"><Avatar name={user.email||app.email}/><div><h2>{user.email||app.email}</h2><small>Patient account</small></div></div><form method="post" action={app.urls.settings} className="settings-form"><label>Phone number<input type="tel" name="phone" required pattern="\+[1-9][0-9]{7,14}" defaultValue={user.phone||''} placeholder="+919876543210"/></label><label>Country<input name="country" required maxLength="100" defaultValue={user.country||'India'}/></label><label>State<input name="state" required maxLength="100" defaultValue={user.state||''}/></label><label>Area / city<input name="area" required maxLength="100" defaultValue={user.area||''}/></label><button className="primary-button">Save profile</button></form><div id="settings" className="privacy-note"><Icon name="shield"/><span><strong>Privacy and security</strong><small>Your reports and requests are scoped to your signed-in account. Sign out when using a shared device.</small></span></div></section></>}

function ComparePage(){const reports=app.reports||[],selected=app.selected||[];return <><PageHeader eyebrow="REPORT TOOLS" title="Compare two reports" subtitle="Select two reports from your account to review shared text and matching measurements."/><form className="panel compare-form" method="post" action={app.urls.compare}><label>Earlier report<select name="first" required defaultValue={selected[0]||''}><option value="" disabled>Choose the first report</option>{reports.map(report=><option key={report.id} value={report.id}>{report.title} · {report.created_at}</option>)}</select></label><label>Later report<select name="second" required defaultValue={selected[1]||''}><option value="" disabled>Choose the second report</option>{reports.map(report=><option key={report.id} value={report.id}>{report.title} · {report.created_at}</option>)}</select></label><button className="primary-button" disabled={reports.length<2}>Compare reports</button>{reports.length<2&&<p>Save at least two reports before comparing them.</p>}</form>{app.result&&<section className="panel comparison-result"><h2>{app.result.first_title} → {app.result.second_title}</h2><p>{app.result.note}</p><p>Text overlap: {app.result.similarity}%</p>{app.result.measurements?.length?app.result.measurements.map((m,i)=><div className="measurement-row" key={i}><strong>{m.label}</strong><span>{m.old} {m.old_unit} → {m.new} {m.new_unit}</span></div>):<p>No matching numeric measurements with the same units were found in both report texts.</p>}</section>}</>}
function ReportPage(){const r=app.report||{};return <><PageHeader eyebrow="MEDICAL RECORD" title={r.title||'Report details'} subtitle={r.created_at}/><section className="panel record-detail">{(app.measurements||[]).filter(item=>Number(item.report_id)===Number(r.id)).length>0&&<><h2>Results with printed reference ranges</h2><div className="measurement-list">{(app.measurements||[]).filter(item=>Number(item.report_id)===Number(r.id)).map((item,index)=><article key={index} className={`measurement-result ${item.abnormal?'abnormal':''}`}><div><strong>{item.name}</strong><small>Reference: {item.reference_range}</small></div><span>{item.value} {item.unit}</span>{item.abnormal&&<b>Outside printed range</b>}</article>)}</div></>}<h2>Extracted report text</h2><pre>{r.content||'No text was extracted from this report.'}</pre><h2>AI explanation</h2>{r.explanation?<pre>{r.explanation}</pre>:<p>Ask the assistant to explain this saved report when you are ready.</p>}<form method="post" action={pathWithId(app.urls.explainReport,r.id)}><button className="primary-button">{r.explanation?'Generate explanation again':'Explain this report'}</button></form><form method="post" action={pathWithId(app.urls.deleteReport,r.id)} onSubmit={e=>{if(!confirm('Delete this report?'))e.preventDefault()}}><button className="danger-button">Delete report</button></form></section></>}
function DashboardContent(){switch(app.page){case 'appointments':return <AppointmentsPage/>;case 'history':return <RecordsPage/>;case 'insights':return <HealthInsights/>;case 'wellness':return <WellnessPage/>;case 'medications':return <MedicationPage/>;case 'upload':return <UploadPage/>;case 'explanation':return <AssistantPage/>;case 'settings':return <SettingsPage/>;case 'compare':return <ComparePage/>;case 'view':return <ReportPage/>;default:return <HomePage/>}}

function DoctorIllustration(){return <div className="doctor-scene" role="img" aria-label="Illustration of a friendly doctor beside a health chart"><div className="doctor-scene-glow"/><svg className="doctor-figure" viewBox="0 0 420 360" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><linearGradient id="coat" x1="0" x2="1" y1="0" y2="1"><stop stopColor="#fff"/><stop offset="1" stopColor="#dff5f2"/></linearGradient><linearGradient id="shirt" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#58c5bd"/><stop offset="1" stopColor="#2ca79f"/></linearGradient></defs><ellipse cx="214" cy="326" rx="112" ry="14" fill="#9ccfca" opacity=".22"/><circle cx="216" cy="164" r="137" fill="#d7f4ef"/><circle cx="216" cy="164" r="108" fill="#eaf9f7"/><g className="doctor-body"><path d="M119 315c3-77 25-111 91-111s89 34 92 111H119Z" fill="url(#coat)"/><path d="m180 214 30 35 31-35 18 101h-99l20-101Z" fill="url(#shirt)"/><path d="m178 215 32 36-26 28-29-51 23-13Zm66 0-32 36 27 28 29-51-24-13Z" fill="#f9ffff"/><path d="m196 239 14 14 14-14-7 63h-14l-7-63Z" fill="#f4bd9b"/><path d="M176 164c0-35 17-59 47-59s48 24 48 59v19c0 34-20 58-48 58s-47-24-47-58v-19Z" fill="#eab798"/><path d="M172 167c-5-44 16-76 53-76 32 0 52 24 51 62-14-6-25-18-29-31-17 18-42 28-75 30v15h-1v-19Z" fill="#293e59"/><path d="M179 166c-8-2-13 4-12 14 1 8 5 14 12 15m87-29c8-2 13 4 12 14-1 8-5 14-12 15" fill="#eab798"/><path d="M194 174v1m44-1v1" stroke="#3e5263" strokeWidth="5" strokeLinecap="round"/><path d="M202 195c8 8 18 8 27 0" fill="none" stroke="#b96f68" strokeWidth="3" strokeLinecap="round"/><path d="M185 161c5-5 12-6 18-3m26 0c6-3 13-2 18 3" fill="none" stroke="#293e59" strokeWidth="4" strokeLinecap="round"/><path d="M184 246v41m62-41v41" stroke="#c9e5e1" strokeWidth="2"/><path d="M193 258c-13 4-18 15-18 28m58-28c13 4 18 15 18 28" fill="none" stroke="#148d87" strokeWidth="5" strokeLinecap="round"/><circle cx="175" cy="288" r="8" fill="#fff" stroke="#148d87" strokeWidth="4"/><path d="M171 315h41" stroke="#d2e6e3" strokeWidth="3" strokeLinecap="round"/></g><g className="doctor-chart"><rect x="28" y="104" width="88" height="116" rx="17" fill="#fff" stroke="#d8ece9" strokeWidth="2"/><rect x="47" y="124" width="50" height="7" rx="3.5" fill="#d8ebe8"/><rect x="47" y="139" width="35" height="6" rx="3" fill="#edf4f3"/><rect x="47" y="160" width="50" height="42" rx="10" fill="#effaf8"/><path d="M54 184h8l7-13 9 22 8-15 7 6h5" fill="none" stroke="#36b8ad" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/></g><g className="doctor-plus"><circle cx="329" cy="91" r="27" fill="#fff"/><path d="M329 79v24m-12-12h24" stroke="#39b9ae" strokeWidth="6" strokeLinecap="round"/></g><g className="doctor-heart"><rect x="300" y="216" width="72" height="64" rx="18" fill="#fff"/><path d="M336 260s-17-10-17-21a10 10 0 0 1 17-7 10 10 0 0 1 17 7c0 11-17 21-17 21Z" fill="#8c83cd"/></g><circle cx="114" cy="260" r="5" fill="#8ad7cd"/><circle cx="313" cy="149" r="4" fill="#a99fe2"/></svg><div className="doctor-note"><span className="doctor-note-icon"><Icon name="shield" size={17}/></span><span><strong>Your health, organized</strong><small>Clear information for your care</small></span></div></div>}

function AuthPage(){const [language,setLanguage]=useState('en');const copy=language==='es'?{features:'Beneficios',explore:'Ver beneficios',login:'Iniciar sesión',start:'Crear cuenta',subtitle:'Entiende tus informes, organiza tus registros y prepara mejores conversaciones con tu equipo médico.',understand:'Entender',organize:'Organizar',manage:'Gestionar',understandBody:'Explicaciones sencillas para los términos de tus informes.',organizeBody:'Tus informes y datos de salud en un solo espacio privado.',manageBody:'Revisa la información y prepara preguntas para tu profesional de salud.'}:{features:'Benefits',explore:'Explore benefits',login:'Log in',start:'Get started',subtitle:'Understand your reports, keep your records together, and prepare for better conversations with your care team.',understand:'Understand',organize:'Organize',manage:'Manage',understandBody:'Get clear explanations of terms in your reports.',organizeBody:'Keep your health records together in one private space.',manageBody:'Review your information and prepare questions for your care team.'};return <div className="hc-landing"><header className="landing-nav" id="top"><Logo/><nav aria-label="Main navigation"><a href="#features">{copy.features}</a><label className="language-picker"><span className="sr-only">Language</span><select value={language} onChange={e=>setLanguage(e.target.value)}><option value="en">English</option><option value="es">Español</option></select></label><a href="/account#login">{copy.login}</a><a className="primary-button" href="/account#register">{copy.start}</a></nav></header><main className="landing-main"><section className="landing-hero landing-hero-public"><div className="landing-hero-copy"><span className="landing-kicker"><Icon name="heart" size={15}/> WELCOME TO YOUR HEALTH SPACE</span><h1>Welcome to Healthcare</h1><p>{copy.subtitle}</p><div className="landing-actions"><a className="primary-button" href="#features">{copy.explore}<Icon name="arrow" size={17}/></a><a className="secondary-button" href="/account#register">{copy.start}</a></div></div></section><section className="landing-features" id="features"><article><span className="feature-glyph"><Icon name="file"/></span><span className="feature-step">01</span><h2>{copy.understand}</h2><p>{copy.understandBody}</p></article><article><span className="feature-glyph mint"><Icon name="shield"/></span><span className="feature-step">02</span><h2>{copy.organize}</h2><p>{copy.organizeBody}</p></article><article><span className="feature-glyph lavender"><Icon name="heart"/></span><span className="feature-step">03</span><h2>{copy.manage}</h2><p>{copy.manageBody}</p></article></section><p className="landing-disclaimer">AI-generated information is educational and does not replace professional medical advice.</p></main><Footer/></div>}

function AccountPage() {
  const authError = new URLSearchParams(window.location.search).get('auth_error');
  const authErrorMessages = {
    login: 'Invalid email or password.',
    'register-details': 'Enter your email, state, and area.',
    'register-password': 'Use at least 10 password characters, including uppercase and lowercase letters, a number, and a symbol.',
    'register-phone': 'Enter your phone in international format, for example +919876543210.',
    'register-account': 'That account could not be created. The email may already be registered.',
  };
  return <div className="hc-landing account-view">
    <header className="landing-nav"><Logo/><a className="secondary-button" href="/">Back to Healthcare</a></header>
    <main className="landing-main">
      <section className="landing-auth" id="account">
        <div className="landing-auth-heading">
          <p className="hc-eyebrow">YOUR PRIVATE HEALTH WORKSPACE</p>
          <h1>Sign in or create an account</h1>
          <p>Reports and saved information are tied to your signed-in account.</p>
          {authErrorMessages[authError] && <p className="text-error" role="alert">{authErrorMessages[authError]}</p>}
        </div>
        <div className="auth-panels">
          <form id="login" className="auth-card" method="post" action={app.urls.login}>
            <h2>Log in</h2>
            <p>Continue to your Healthcare dashboard.</p>
            {app.firebase && <><button type="button" className="google-button" onClick={googleLogin}>Continue with Google</button><p className="auth-google-error" role="alert"/></>}
            <label>Email<input name="email" type="email" required autoComplete="email"/></label>
            <label>Password<input name="password" type="password" required autoComplete="current-password"/></label>
            <button className="primary-button">Log in</button>
          </form>
          <form id="register" className="auth-card" method="post" action={app.urls.register}>
            <h2>Create your account</h2>
            <p>Start organizing your health information.</p>
            <label>Email<input name="email" type="email" required autoComplete="email"/></label>
            <label>Password
              <input
                name="password"
                type="password"
                minLength="10"
                pattern="(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9])(?=.*[^A-Za-z0-9]).{10,}"
                title="Use at least 10 characters, including uppercase and lowercase letters, a number, and a symbol."
                required
                autoComplete="new-password"
              />
            </label>
            <p className="auth-password-hint">Use at least 10 characters, including uppercase and lowercase letters, a number, and a symbol.</p>
            <label>Phone number<input name="phone" type="tel" pattern="\+[1-9][0-9]{7,14}" placeholder="+919876543210" required/></label>
            <label>Country<input name="country" defaultValue="India" required/></label>
            <label>State<input name="state" required maxLength="100"/></label>
            <label>Area / city<input name="area" required maxLength="100"/></label>
            <button className="primary-button">Get started</button>
          </form>
        </div>
      </section>
    </main>
    <Footer/>
  </div>
}
async function googleLogin(){const button=document.querySelector('.google-button');if(button)button.disabled=true;try{const firebase=app.firebase;if(!firebase)throw Error('Google sign-in is not configured.');const sdk=await import('https://www.gstatic.com/firebasejs/12.19.0/firebase-app.js');const authSdk=await import('https://www.gstatic.com/firebasejs/12.19.0/firebase-auth.js');const instance=sdk.initializeApp(firebase);const result=await authSdk.signInWithPopup(authSdk.getAuth(instance),new authSdk.GoogleAuthProvider());const response=await api(app.urls.google,{method:'POST',body:JSON.stringify({idToken:await result.user.getIdToken()})});location.assign(response.needsProfile?app.urls.profile:app.urls.dashboard)}catch(error){const msg=document.querySelector('.auth-google-error');if(msg)msg.textContent=error.message;else alert(error.message);if(button)button.disabled=false}}
function ProfileCompletion(){const account=app.account||{};return <div className="auth-page"><header className="auth-header"><Logo/></header><main className="profile-complete"><h1>Complete your profile</h1><p>Add contact and location details to finish setting up your account.</p><form className="auth-card" method="post"><label>Phone number<input name="phone" type="tel" pattern="\+[1-9][0-9]{7,14}" required defaultValue={account.phone||''}/></label><label>Country<input name="country" required defaultValue={account.country||'India'}/></label><label>State<input name="state" required defaultValue={account.state||''}/></label><label>Area / city<input name="area" required defaultValue={account.area||''}/></label><button className="primary-button">Save and continue</button></form></main><FlashMessages/><Footer/></div>}

function App(){const [menuOpen,setMenuOpen]=useState(false);useEffect(()=>{document.title=app.page==='appointments'?'Appointments | Healthcare':app.view==='landing'?'Healthcare | AI-Powered Personal Health Copilot':`${app.page||'Home'} | Healthcare`},[]);if(app.view==='landing')return <AuthPage/>;if(app.view==='account')return <AccountPage/>;if(app.view==='profile')return <ProfileCompletion/>;return <div className="hc-app"><Topbar onMenu={()=>setMenuOpen(true)}/><Sidebar page={app.page} open={menuOpen} close={()=>setMenuOpen(false)}/><main className="hc-main"><FlashMessages/><DashboardContent/><Footer/></main></div>}

createRoot(document.getElementById('root')).render(<App/>);
